import{_ as s,o as e,c as i,a2 as t}from"./chunks/framework.doxMM-x8.js";const k=JSON.parse('{"title":"快速开始","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/getting-started/quickstart","contentType":"guide","prev":{"text":"项目文档","link":"/docs/"},"next":{"text":"Lab 与资产库","link":"/guides/lab-viewer"}},"headers":[],"relativePath":"getting-started/quickstart.md","filePath":"getting-started/quickstart.md"}'),r={name:"getting-started/quickstart.md"};function n(l,a,h,d,p,o){return e(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>目标：从源码启动 Lab Word 现有应用，并用 HTTP 和 Web 页面确认开发环境可用。已验证的 Viewer 体验目前来自<a href="./../guides/lab-viewer">独立预览</a>，正式 Lab 集成验收另行记录。</p><h2 id="_1-安装并启动" tabindex="-1">1. 安装并启动 <a class="header-anchor" href="#_1-安装并启动" aria-label="Permalink to &quot;1. 安装并启动&quot;">​</a></h2><p>准备 Docker/Compose，以及仓库固定版本：Rust 1.96.0、Node 24.18.0、pnpm 11.17.0、just 1.58.0。版本以<a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/rust-toolchain.toml" target="_blank" rel="noreferrer">工具链</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/.node-version" target="_blank" rel="noreferrer">Node</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/package.json" target="_blank" rel="noreferrer">包配置</a>和<a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/.tool-versions" target="_blank" rel="noreferrer">工具版本</a>为准。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/CaiZongyuan/labworld.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> labworld</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>命令在仓库根目录执行。首次启动下载依赖并编译 Rust。开发脚本启动 PostgreSQL、Redis、RustFS、Mailpit，执行迁移、初始化存储，再运行 API、Worker 和 Web。它会在本地开发卷写入数据。</p><p>默认设置来自 <a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/.env.example" target="_blank" rel="noreferrer">.env.example</a>；需要调整时建立未跟踪的 <code>.env</code>。API 配置见<a href="./../reference/config">生成参考</a>。</p><h2 id="_2-观察结果" tabindex="-1">2. 观察结果 <a class="header-anchor" href="#_2-观察结果" aria-label="Permalink to &quot;2. 观察结果&quot;">​</a></h2><p>保持开发入口运行，在另一个终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/system/status</span></span></code></pre></div><p>预期均为 HTTP 200，响应含 <code>x-request-id</code>。live 表示进程运行；ready 核对依赖与迁移；status 返回实际系统状态。</p><p>打开 <a href="http://127.0.0.1:5173/register" target="_blank" rel="noreferrer">http://127.0.0.1:5173/register</a> 创建开发账号。首个账号为 Owner，后续为 Member；密码长度 12–128 字符。开发邮件在 <a href="http://127.0.0.1:8025" target="_blank" rel="noreferrer">http://127.0.0.1:8025</a> 查看。已有平台可以验证登录与业务操作，Lab 体验以相应版本的集成验收为准。</p><h2 id="_3-检查依赖失败与恢复" tabindex="-1">3. 检查依赖失败与恢复 <a class="header-anchor" href="#_3-检查依赖失败与恢复" aria-label="Permalink to &quot;3. 检查依赖失败与恢复&quot;">​</a></h2><p>只在自己的开发环境停止 PostgreSQL：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db-down</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span></code></pre></div><p>ready 应为 503，live 仍为 200。恢复数据库：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span></code></pre></div><p>ready 应恢复 200。迁移不匹配时核对源码版本并执行 <code>just migrate</code>。API 启动不自动迁移；新增 SQL 后执行迁移并重启开发入口，使二进制中的迁移集合刷新。</p><h2 id="停止与下一步" tabindex="-1">停止与下一步 <a class="header-anchor" href="#停止与下一步" aria-label="Permalink to &quot;停止与下一步&quot;">​</a></h2><p><code>Ctrl+C</code> 停止 API、Worker 和 Web；<code>just services-down</code> 停止容器并保留卷。端口冲突时同步核对 APP_BIND、VITE_API_PROXY 与 APP_ORIGIN；数据库端口变更同时调整 POSTGRES_PORT 和 DATABASE_URL。</p><p>接下来<a href="./../guides/lab-viewer">运行 Lab Viewer 预览</a>，或阅读<a href="./../architecture/project-structure">项目结构</a>。文档本身通过 <code>just docs</code> 启动，地址为 <a href="http://127.0.0.1:5174/labworld/docs/" target="_blank" rel="noreferrer">http://127.0.0.1:5174/labworld/docs/</a>。</p><hr><p>源码版本：<code>ddaf175ca215</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/ddaf175ca2158c3cd0c6d2ad8d29ecae7ea561d3/docs/getting-started/quickstart.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,23)])])}const g=s(r,[["render",n]]);export{k as __pageData,g as default};
